using System;using System.Diagnostics;using System.IO;using System.Net;using System.Net.Sockets;using System.Text;using System.Threading;
internal static class Program{
static readonly string Root=AppDomain.CurrentDomain.BaseDirectory;
[STAThread]static void Main(){int port=FreePort();var server=new HttpListener();server.Prefixes.Add("http://127.0.0.1:"+port+"/");server.Start();Process.Start("http://127.0.0.1:"+port+"/apps/web/index.html");while(server.IsListening){try{var c=server.GetContext();ThreadPool.QueueUserWorkItem(_=>Serve(c));}catch(HttpListenerException){break;}}}
static int FreePort(){var s=new TcpListener(IPAddress.Loopback,0);s.Start();int p=((IPEndPoint)s.LocalEndpoint).Port;s.Stop();return p;}
static void Serve(HttpListenerContext c){string rel=Uri.UnescapeDataString(c.Request.Url.AbsolutePath.TrimStart('/')).Replace('/',Path.DirectorySeparatorChar);if(rel=="health"){Write(c,Encoding.UTF8.GetBytes("{\"application\":\"LMN\",\"status\":\"ready\",\"offline\":true}"),"application/json");return;}string path=Path.GetFullPath(Path.Combine(Root,rel));if(!path.StartsWith(Path.GetFullPath(Root),StringComparison.OrdinalIgnoreCase)||!File.Exists(path)){c.Response.StatusCode=404;c.Response.Close();return;}string ext=Path.GetExtension(path).ToLowerInvariant();string type=ext==".html"?"text/html; charset=utf-8":ext==".js"?"text/javascript; charset=utf-8":ext==".css"?"text/css; charset=utf-8":ext==".json"||ext==".webmanifest"?"application/json; charset=utf-8":"application/octet-stream";Write(c,File.ReadAllBytes(path),type);}
static void Write(HttpListenerContext c,byte[] b,string type){c.Response.ContentType=type;c.Response.ContentLength64=b.Length;c.Response.OutputStream.Write(b,0,b.Length);c.Response.Close();}}
